package com.aaliyun.leadnews.search.config;
import com.aaliyun.leadnews.model.search.ArticleSearchEvent;import org.apache.kafka.common.TopicPartition;import org.springframework.context.annotation.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.kafka.listener.*;import org.springframework.kafka.support.ExponentialBackOffWithMaxRetries;import org.springframework.kafka.support.serializer.JsonDeserializer;
@Configuration public class KafkaSearchConfiguration{@Bean DefaultErrorHandler searchErrorHandler(KafkaTemplate<Object,Object> kafka){DeadLetterPublishingRecoverer recoverer=new DeadLetterPublishingRecoverer(kafka,(r,e)->new TopicPartition("leadnews.article.search.DLT",r.partition()));ExponentialBackOffWithMaxRetries backoff=new ExponentialBackOffWithMaxRetries(3);backoff.setInitialInterval(1000);backoff.setMultiplier(2);backoff.setMaxInterval(5000);return new DefaultErrorHandler(recoverer,backoff);}}
